<script lang="ts">
  import { onMount,onDestroy } from 'svelte';import { ask } from '@tauri-apps/plugin-dialog';
  import { roadmapSystemApi as desktop,type InstalledApp,type AppLeftover } from '#lib/roadmap-system-api.ts';
  import { fileApi,formatBytes } from '#lib/file-api.ts';import { createJob,type JobHandle,type JobProgress } from '#lib/jobs.ts';
  import Notice from '#lib/ui/Notice.svelte';import ProgressBar from '#lib/ui/ProgressBar.svelte';
  let apps=$state<InstalledApp[]>([]),query=$state(''),selected=$state(''),review=$state<InstalledApp|null>(null),leftovers=$state<AppLeftover[]>([]),checked=$state<string[]>([]);
  let busy=$state(false),error=$state(''),message=$state(''),progress=$state<JobProgress|null>(null);let job=$state<JobHandle|null>(null);let requestId=0;
  const filtered=$derived(apps.filter((app)=>`${app.name} ${app.publisher}`.toLowerCase().includes(query.toLowerCase())));
  const bytes=$derived(leftovers.filter((l)=>checked.includes(l.path)).reduce((sum,l)=>sum+l.bytes,0));
  function choose(id:string){selected=id;review=apps.find((app)=>app.id===id)??null;leftovers=[];checked=[];message='';}
  async function refresh(){const id=++requestId;busy=true;error='';try{const next=await desktop.installedApps();if(id===requestId){apps=next;if(!review)choose(next[0]?.id??'');}}catch(e){if(id===requestId)error=e instanceof Error?e.message:String(e);}finally{if(id===requestId)busy=false;}}
  async function uninstall(){if(!review || busy)return;const app={...review},id=++requestId;busy=true;error='';message='';try{if(!await ask(`Start the registered uninstaller for ${app.name}?\n\nPublisher: ${app.publisher || 'Not registered'}\n\nExact command:\n${app.command}\n\nThe vendor's uninstaller controls what it removes and may ask for administrator approval. Oxbox never bypasses those prompts.`,{title:'Review registered uninstaller',kind:'warning'}))return;if(id!==requestId)return;const pid=await desktop.uninstall(app.id,app.command,true);if(id===requestId)message=`Uninstaller started (PID ${pid}). Complete its prompts, then refresh the application list. User-data candidates are kept unless you separately review and trash them.`;}catch(e){if(id===requestId)error=e instanceof Error?e.message:String(e);}finally{if(id===requestId)busy=false;}}
  async function scan(){if(!review || busy)return;const app={...review},id=++requestId;busy=true;error='';message='';leftovers=[];checked=[];progress=null;const running=createJob('uninstall-apps',(p)=>{if(id===requestId)progress=p;});job=running;try{const next=await running.run((jobId)=>desktop.leftovers(jobId,app.name,app.publisher));if(id===requestId){leftovers=next;if(!next.length)message='No exact-name user-data candidates found. Oxbox does not guess folder names.';}}catch(e){if(id===requestId)error=e instanceof Error?e.message:String(e);}finally{if(id===requestId){busy=false;job=null;}}}
  async function trash(){if(!checked.length || busy)return;const paths=[...checked],total=bytes,id=++requestId;busy=true;error='';try{if(!await ask(`Move these ${paths.length} user-data folders (${formatBytes(total)}) to the Recycle Bin / Trash?\n\n${paths.join('\n')}\n\nThese folders can contain settings and personal data. Confirm only after reviewing their contents and finishing the uninstaller.`,{title:'Review user-data cleanup',kind:'warning'}))return;if(id!==requestId)return;const count=await fileApi.trashFiles(paths,true);if(id===requestId){leftovers=leftovers.filter((l)=>!paths.includes(l.path));checked=[];message=`Moved ${count} reviewed folders to Trash.`;}}catch(e){if(id===requestId)error=e instanceof Error?e.message:String(e);}finally{if(id===requestId)busy=false;}}
  onMount(()=>{void refresh();});onDestroy(()=>{requestId++;void job?.cancel().catch(()=>{});});
</script>
<div class="tool" aria-busy={busy}>
  <Notice kind="info">Lists registered Windows desktop uninstallers. Review the exact command before starting it. Store apps and script-based uninstallers should be removed through Windows Installed apps. Oxbox does not force removal.</Notice>
  <button class="btn" disabled={busy} onclick={refresh}>Refresh installed applications</button>
  <label class="field"><span class="field-label">Search name or publisher</span><input class="input" type="search" bind:value={query} disabled={busy} /></label>
  <label class="field"><span class="field-label">Registered desktop application</span><select class="input" value={selected} onchange={(e)=>choose(e.currentTarget.value)} disabled={busy}><option value="">Choose an application</option>{#each filtered as app}<option value={app.id}>{app.name}{app.version?` · ${app.version}`:''}{app.publisher?` · ${app.publisher}`:''}</option>{/each}</select></label>
  {#if review}<section class="card review"><strong>{review.name}</strong><p>{review.publisher || 'Publisher not registered'} · {review.version || 'Version not registered'}</p><span class="field-label">Registered uninstall command</span><code class="command mono">{review.command}</code>{#if review.installLocation}<p class="command">Install location: {review.installLocation}</p>{/if}</section><div class="row"><button class="btn btn-primary" disabled={busy} onclick={uninstall}>Review and start uninstaller…</button><button class="btn" disabled={busy} onclick={scan}>Scan exact-name user-data folders</button></div>{/if}
  {#if busy && job}<ProgressBar {progress} oncancel={()=>{void job?.cancel().catch((e)=>{error=String(e);});}} />{/if}
  {#each leftovers as item}<label class="card choice"><input type="checkbox" checked={checked.includes(item.path)} disabled={busy} onchange={(e)=>{checked=e.currentTarget.checked?[...checked,item.path]:checked.filter((p)=>p!==item.path);}} /><span class="command">{item.path}<small>{item.files} files · {formatBytes(item.bytes)}</small></span></label>{/each}
  {#if leftovers.length}<Notice kind="info">These are exact-name candidates under your AppData folders, not proof that they are unused. No candidate is selected automatically.</Notice><button class="btn" disabled={busy || !checked.length} onclick={trash}>Review and trash selected folders ({formatBytes(bytes)})…</button>{/if}
  {#if message}<Notice kind="success">{message}</Notice>{/if}{#if error}<Notice kind="error">{error}</Notice>{/if}
</div>
<style>.tool{display:grid;gap:var(--s-4)}.review{display:grid;gap:var(--s-2);padding:var(--s-4)}.row{display:flex;gap:var(--s-3);flex-wrap:wrap}.command{overflow-wrap:anywhere;white-space:pre-wrap}.choice{display:flex;gap:var(--s-3);padding:var(--s-4)}small{display:block;color:var(--text-3);font-size:var(--text-sm)}</style>
